using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Net;
using System.Text;
using System.Threading;
using System.Web.Script.Serialization;
namespace PZ3D {
 static class ComponentCache {
  public static void ExtractZip(string zip,string target){Directory.CreateDirectory(target);using(var a=ZipFile.OpenRead(zip)){foreach(var e in a.Entries){string rel=e.FullName.Replace('\\','/').TrimEnd('/');if(rel.Length==0)continue;string p=DlssInstaller.SafePath(target,rel);if(e.FullName.EndsWith("/")){Directory.CreateDirectory(p);continue;}Directory.CreateDirectory(Path.GetDirectoryName(p));using(var input=e.Open())using(var output=File.Create(p))input.CopyTo(output);}}}
  static void FileFromZip(string zip,string name,string target){using(var a=ZipFile.OpenRead(zip)){var files=a.Entries.Where(e=>string.Equals(Path.GetFileName(e.FullName),name,StringComparison.OrdinalIgnoreCase)).ToArray();if(files.Length!=1)throw new Exception("归档中目标文件不唯一或缺失："+name);Directory.CreateDirectory(Path.GetDirectoryName(target));using(var input=files[0].Open())using(var output=File.Create(target))input.CopyTo(output);}}
  static void Download(string url,string path,Action<int,string> progress,int stage,CancellationToken cancel,string expected=null){if(progress!=null)progress(stage,"下载 "+Path.GetFileName(path));Directory.CreateDirectory(Path.GetDirectoryName(path));var request=(HttpWebRequest)WebRequest.Create(url);request.UserAgent="Orange3DTool/2.0";request.Timeout=20000;request.ReadWriteTimeout=30000;using(var response=request.GetResponse())using(var stream=response.GetResponseStream())using(var output=File.Create(path)){byte[] buffer=new byte[131072];long total=response.ContentLength,done=0;int read;DateTime last=DateTime.MinValue;while((read=stream.Read(buffer,0,buffer.Length))>0){cancel.ThrowIfCancellationRequested();output.Write(buffer,0,read);done+=read;if(progress!=null&&(DateTime.UtcNow-last).TotalMilliseconds>250){progress(stage,Path.GetFileName(path)+" · "+(done/1048576.0).ToString("F1")+" / "+(total>0?(total/1048576.0).ToString("F1"):"?")+" MB");last=DateTime.UtcNow;}}}if(expected!=null&&!string.Equals(DlssInstaller.HashFile(path),expected,StringComparison.OrdinalIgnoreCase))throw new Exception("下载 SHA256 与作者发布值不符："+Path.GetFileName(path));}
  static void ReShade(string setup,string destination){byte[] b=File.ReadAllBytes(setup);int start=-1;for(int i=b.Length-22;i>=Math.Max(0,b.Length-65557);i--)if(b[i]==0x50&&b[i+1]==0x4b&&b[i+2]==5&&b[i+3]==6){long origin=(long)i-BitConverter.ToUInt32(b,i+12)-BitConverter.ToUInt32(b,i+16);if(origin>=0&&origin<=int.MaxValue&&origin+4<b.Length&&b[(int)origin]==0x50&&b[(int)origin+1]==0x4b){start=(int)origin;break;}}if(start<0)throw new Exception("ReShade 安装包内未找到有效 ZIP；未执行安装程序。");using(var m=new MemoryStream(b,start,b.Length-start))using(var a=new ZipArchive(m,ZipArchiveMode.Read)){var e=a.GetEntry("ReShade64.dll");if(e==null)throw new Exception("ReShade64.dll 不在官方安装包中。");using(var input=e.Open())using(var output=File.Create(destination))input.CopyTo(output);}string ascii=Encoding.ASCII.GetString(File.ReadAllBytes(destination));if(!ascii.Contains("ReShadeRegisterAddon")||!ascii.Contains("ReShadeUnregisterAddon"))throw new Exception("ReShade DLL 没有附加组件 API。");var version=FileVersionInfo.GetVersionInfo(destination);if(version.FileMajorPart<6||(version.FileMajorPart==6&&version.FileMinorPart<8))throw new Exception("ReShade 版本低于 6.8。");}
  public static string Prepare(string root,Action<int,string> progress,CancellationToken cancel){
   Directory.CreateDirectory(root);string stage=Path.Combine(root,"staging-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(stage);string payload=Path.Combine(stage,"payload");Directory.CreateDirectory(payload);var provenance=new List<object>();
   string feeder="https://github.com/jlrouzies-fr/DLSS5-Feeder/releases/download/v1.18.0-beta.1/DLSS5-Feeder-1.18.0-beta.1.zip";string feederZip=Path.Combine(stage,"feeder.zip");Download(feeder,feederZip,progress,5,cancel,"DF5E5DD5D15A88DE73885AD164FE6BF9E6CAFC728DB1133B9BE3FC8A25F5BBCB");FileFromZip(feederZip,"dlss5-feed.addon64",Path.Combine(payload,"dlss5-feed.addon64"));FileFromZip(feederZip,"DLSS5_Feed.fx",Path.Combine(payload,"reshade-shaders","Shaders","DLSS5_Feed.fx"));provenance.Add(new{source=feeder,sha256=DlssInstaller.HashFile(feederZip),note="上游固定实验版本，不宣称最新"});
   string reshape="https://reshade.me/downloads/ReShade_Setup_6.8.0_Addon.exe";string setup=Path.Combine(stage,"ReShade_Setup.exe");Download(reshape,setup,progress,20,cancel);ReShade(setup,Path.Combine(payload,"opengl32.dll"));provenance.Add(new{source=reshape,sha256=DlssInstaller.HashFile(setup),note="只读取内嵌 DLL；不运行安装器"});
   foreach(string name in new[]{"ReShade.fxh","ReShadeUI.fxh","DrawText.fxh"}){string url="https://raw.githubusercontent.com/crosire/reshade-shaders/slim/Shaders/"+name;Download(url,Path.Combine(payload,"reshade-shaders","Shaders",name),progress,30,cancel);provenance.Add(new{source=url,note="ReShade framework header"});}
   string lumen="https://codeload.github.com/umar-afzaal/LumeniteFX/zip/refs/heads/mainline";string lumenZip=Path.Combine(stage,"Lumenite.zip");Download(lumen,lumenZip,progress,40,cancel);string unpack=Path.Combine(stage,"lumen");ExtractZip(lumenZip,unpack);foreach(string p in Directory.GetFiles(unpack,"*",SearchOption.AllDirectories)){string rel=p.Substring(unpack.Length+1).Replace('\\','/');int index=rel.IndexOf("/Shaders/",StringComparison.Ordinal);int textures=rel.IndexOf("/Textures/",StringComparison.Ordinal);if(index>=0||textures>=0){string output="reshade-shaders/"+rel.Substring((index>=0?index:textures)+1);string target=DlssInstaller.SafePath(payload,output);Directory.CreateDirectory(Path.GetDirectoryName(target));File.Copy(p,target);}else if(Path.GetFileName(p).IndexOf("license",StringComparison.OrdinalIgnoreCase)>=0||Path.GetFileName(p).IndexOf("credit",StringComparison.OrdinalIgnoreCase)>=0){string target=Path.Combine(payload,"licenses","Lumenite-"+Path.GetFileName(p));Directory.CreateDirectory(Path.GetDirectoryName(target));File.Copy(p,target);}}provenance.Add(new{source=lumen,sha256=DlssInstaller.HashFile(lumenZip),note="运动向量估计；mainline 下载快照"});
   string[,] pieces={{"renodx-dlss5.addon64","renodx-dlss5-7.0.0-rc8/renodx-dlss5_7.0.0-rc8.zip"},{"nvngx_dlss.dll","dlss-310.9.1/nvngx_dlss_310.9.1.zip"},{"nvngx_dlssnr.dll","dlssnr-310.8.Lecram/nvngx_dlssnr_310.8.Lecram.zip"}};for(int i=0;i<3;i++){string url="https://github.com/RankFTW/rhi-repo/releases/download/"+pieces[i,1];string zip=Path.Combine(stage,pieces[i,0]+".zip");Download(url,zip,progress,55+i*10,cancel);FileFromZip(zip,pieces[i,0],Path.Combine(payload,pieces[i,0]));provenance.Add(new{source=url,sha256=DlssInstaller.HashFile(zip),note=i==2?"上游安装器指定的第三方修改运行库，不是 NVIDIA 官方下载":"上游实验安装器指定的组件分发源"});}
   foreach(var license in new[]{new[]{"Feeder-LICENSE.txt","https://raw.githubusercontent.com/jlrouzies-fr/DLSS5-Feeder/v1.18.0-beta.1/LICENSE"},new[]{"ReShade-LICENSE.txt","https://raw.githubusercontent.com/crosire/reshade/v6.8.0/LICENSE.md"}}){try{Download(license[1],Path.Combine(payload,"licenses",license[0]),progress,90,cancel);}catch(Exception e){provenance.Add(new{source=license[1],note="许可下载未完成，请查原作者页面："+e.Message});}}
   DlssInstaller.ValidateCache(payload);File.WriteAllText(Path.Combine(payload,"sources.json"),new JavaScriptSerializer().Serialize(provenance),new UTF8Encoding(false));if(progress!=null)progress(100,"完整 DLSS 实验组件已准备（固定兼容组合，尚未游戏内验证）");return payload;
  }
 }
}
